export function validatePathParam(paramName: string, value: unknown): string {
  // Checks for empty, unsafe characters, finite numbers
  if (value === null || value === undefined || value === '') {
    throw buildError(`Path parameter '${paramName}' must not be empty`, 'VALIDATION_ERROR');
  }
  const str = `${value as string | number}`;
  if (UNSAFE_PATH_CHARS.test(str)) {
    throw buildError(`Path parameter '${paramName}' contains invalid characters`, 'VALIDATION_ERROR');
  }
  if (typeof value === 'number' && !Number.isFinite(value)) {
    throw buildError(`Path parameter '${paramName}' must be a finite number`, 'VALIDATION_ERROR');
  }
  return str;
}

export function validateBaseUrl(url: string, allowCustomHost?: boolean): string {
  // HTTPS-only, host allowlist validation
}

export function validateQueryParam(paramName: string, value: unknown): string {
  // Not null/undefined, length < 2000, finite numbers
}
```

**Error Handling with Type Guards** (`/d/code/ESI.ts/src/core/util/error.ts`):
```typescript
export class EsiError extends Error {
  constructor(
    public readonly statusCode: number,
    message: string,
    url?: string,
    public readonly requestId?: string,
  ) { }

  isRateLimited(): boolean { return this.statusCode === 420 || this.statusCode === 429; }
  isNotFound(): boolean { return this.statusCode === 404; }
  isUnauthorized(): boolean { return this.statusCode === 401; }
  isForbidden(): boolean { return this.statusCode === 403; }
  isServerError(): boolean { return this.statusCode >= 500; }
  isTimeout(): boolean { return this.statusCode === 0; }
  get retryable(): boolean { ... }
}

// Type guard functions
export function isEsiError(error: unknown): error is EsiError { ... }
export function isRateLimited(error: unknown): error is EsiError { ... }
export function isNotFound(error: unknown): error is EsiError { ... }
// ... etc for other error types
```

